package main

import "fmt"

func main() {
	score := 85

	// if 带初始化语句
	if v := score * 2; v > 150 {
		fmt.Println("分数很高:", v)
	} else {
		fmt.Println("普通分数:", v)
	}

	// if / else if / else
	if score >= 90 {
		fmt.Println("优秀")
	} else if score >= 60 {
		fmt.Println("及格")
	} else {
		fmt.Println("不及格")
	}

	// switch 带初始化语句
	switch grade := score / 10; grade {
	case 9:
		fmt.Println("等级 A")
	case 8:
		fmt.Println("等级 B")
	default:
		fmt.Println("等级 C")
	}

	// switch 不带表达式
	switch {
	case score >= 90:
		fmt.Println("很棒")
	case score >= 60:
		fmt.Println("还行")
	default:
		fmt.Println("加油")
	}

	// fallthrough
	switch score / 20 {
	case 4:
		fmt.Println("高分档")
		fallthrough
	case 3:
		fmt.Println("接近高分")
	}
}
